<?php
namespace App\Http\Controllers\Api;
use App\Models\GateCommand;use App\Models\User;use Illuminate\Http\Request;
class GateController{private function device(Request $r){abort_unless($r->header('X-SmartGate-Device')&&hash_equals((string)env('ESP32_DEVICE_KEY',''),(string)$r->header('X-SmartGate-Device')),401);}public function override(Request $r){$u=User::findOrFail($r->session()->get('user_id'));abort_unless(in_array($u->role,['guard','admin','super_admin']),403);$d=$r->validate(['gate'=>'required|in:entry,exit','emergency'=>'boolean']);return ['ok'=>true,'command_id'=>GateCommand::create(['device_id'=>env('ESP32_DEVICE_ID','180503'),'gate'=>$d['gate'],'command'=>'open','status'=>'pending','requested_by'=>$u->id,'reason'=>!empty($d['emergency'])?'EMERGENCY':'MANUAL'])->id];}public function commands(Request $r){$this->device($r);return ['ok'=>true,'commands'=>GateCommand::where('status','pending')->orderBy('id')->limit(10)->get()];}public function complete(Request $r,$id){$this->device($r);$c=GateCommand::findOrFail($id);$c->update(['status'=>'completed']);return ['ok'=>true];}public function heartbeat(Request $r){$this->device($r);return ['ok'=>true];}public function status(){return ['ok'=>true,'gate'=>'online'];}}
